export function flightRounds(round = 0) { return Array.from({ length: 3 }, (_, i) => ({ ...FLIGHT_EVENTS[(round * 3 + i) % FLIGHT_EVENTS.length], target: FLIGHT_EVENTS[(round * 3 + i) % FLIGHT_EVENTS.length].kind === 'dial' ? 20 + ((round * 23 + i * 19) % 65) : undefined })); }
export function flightAnswer(event, value) { return event.kind === 'dial' ? Math.abs(value - (event.target ?? 50)) <= 5 : Number(value) === event.right; }
